import base64,io,pathlib,subprocess,tarfile
root=pathlib.Path('/home/zbs/rf-round7-live-window-20261019');lab=root/'lab';lab.mkdir(exist_ok=False)
with tarfile.open(fileobj=io.BytesIO(base64.b64decode('')),mode='r:gz') as tf:
 for m in tf.getmembers():
  if not (lab/m.name).resolve().is_relative_to(lab) or not m.isfile():raise RuntimeError('Unsafe archive')
 tf.extractall(lab,filter='data')
p=subprocess.run(['python3',str(lab/'scripts/round7_live_build.py'),'--root',str(root)])
raise SystemExit(p.returncode)
